THEME = ("T10", "Identités, authentification forte et comptes à privilèges")
SOURCE = "NIST SP 800-63B (2017, rév. 3) ; FIDO Alliance, FIDO2/WebAuthn (W3C, 2019) ; RFC 6238 (TOTP) ; OASIS SAML 2.0 ; OpenID Connect Core 1.0 ; RFC 6749 (OAuth 2.0) ; RFC 7644 (SCIM) ⚠ à vérifier"
Q = [
(1,"Que signifie MFA ?","Authentification multifacteur","Mot de passe fort et automatique","Message de fin d'accès","Module de filtrage avancé",
 "Elle combine au moins deux facteurs de familles différentes."),
(1,"Quelle combinaison est réellement une authentification à deux facteurs ?","Mot de passe et code d'une application sur le téléphone","Mot de passe et question secrète","Deux mots de passe","Un code PIN et un mot de passe",
 "Les deux éléments doivent appartenir à des familles différentes : savoir et posséder."),
(2,"Pourquoi la question secrète n'est-elle pas un second facteur ?","Elle appartient à la même famille « ce que je sais »","Elle est trop courte","Elle est chiffrée","Elle est publique",
 "Et elle est souvent devinable ou retrouvable en ligne."),
(2,"Que signifie TOTP ?","Mot de passe à usage unique basé sur le temps","Transfert sécurisé de paquets","Test de pénétration","Protocole de transport",
 "Le code change toutes les 30 secondes à partir d'un secret partagé (RFC 6238)."),
(2,"Quel est le risque d'un code SMS comme second facteur ?","Il peut être intercepté ou détourné par échange de carte SIM","Il est trop long","Il est trop secret","Il est chiffré",
 "Le SMS est considéré comme un facteur faible par rapport aux clés matérielles."),
(2,"Quelle méthode MFA est résistante à l'hameçonnage ?","Une clé de sécurité FIDO2 ou une passkey","Un code SMS","Une question secrète","Un mot de passe long",
 "La clé vérifie le domaine du site : un faux site ne reçoit rien d'exploitable."),
(2,"Qu'est-ce qu'une passkey ?","Un identifiant cryptographique lié à l'appareil et au site, sans mot de passe à saisir","Un mot de passe très long","Un badge physique","Un code papier",
 "Elle repose sur une paire de clés : la clé privée reste sur l'appareil."),
(3,"Quelle attaque contourne une MFA par notification en saturant l'utilisateur de demandes ?","La fatigue MFA (MFA bombing)","L'injection SQL","Le déni de service réseau","L'attaque par dictionnaire",
 "L'utilisateur finit par accepter une demande pour faire cesser les notifications."),
(3,"Quelle mesure répond à la fatigue MFA ?","Une validation par nombre à saisir et la limitation des demandes","Autoriser sans MFA","Envoyer plus de notifications","Supprimer les journaux",
 "Faire saisir un nombre affiché sur l'écran de connexion oblige à lire le contexte."),
(2,"Que fait la fédération d'identités ?","Permet d'utiliser une identité d'un fournisseur pour accéder à des applications d'une autre organisation","Fusionne des bases de données","Chiffre les mots de passe","Supprime les rôles",
 "Les applications délèguent l'authentification à un fournisseur d'identité de confiance."),
(2,"Quel standard est très utilisé pour le SSO d'entreprise via des assertions XML ?","SAML 2.0","FTP","SMTP","SNMP",
 "SAML transmet des assertions signées entre fournisseur d'identité et fournisseur de service."),
(2,"Quel protocole sert à déléguer l'accès à des ressources sans partager le mot de passe ?","OAuth 2.0","Telnet","DHCP","NTP",
 "Il délivre des jetons d'accès limités en portée et en durée."),
(2,"À quoi sert OpenID Connect ?","À ajouter une couche d'authentification (identité) à OAuth 2.0","À chiffrer les disques","À sauvegarder les mots de passe","À filtrer le courrier",
 "Il fournit un jeton d'identité en plus du jeton d'accès."),
(3,"Quelle différence entre un jeton d'identité et un jeton d'accès ?","Le jeton d'identité dit qui est l'utilisateur ; le jeton d'accès autorise des appels à une API","Ils sont identiques","Le jeton d'identité est un mot de passe","Le jeton d'accès est un certificat",
 "Le premier est destiné à l'application cliente, le second à l'API protégée."),
(2,"Quelle bonne pratique s'applique à la durée d'un jeton d'accès ?","La limiter à quelques minutes ou heures","La rendre illimitée","La rendre publique","La stocker en clair partout",
 "Un jeton volé aura une durée d'utilisation réduite."),
(2,"Que fait SCIM ?","Automatise la création, la mise à jour et la suppression des comptes entre systèmes","Chiffre les courriels","Gère les câbles","Compresse les journaux",
 "SCIM (RFC 7644) standardise le provisioning des identités."),
(2,"Que désigne le cycle JML ?","Arrivée, mobilité, départ (joiner, mover, leaver)","Java, Maven, Linux","Journal, Message, Log","Jeton, Mot de passe, Licence",
 "Chaque étape déclenche une création, une adaptation ou un retrait de droits."),
(2,"Quelle étape du JML est la plus souvent oubliée dans la pratique ?","La mobilité (retrait des anciens droits)","L'arrivée","Le départ du bâtiment","L'attribution du bureau",
 "Les personnes accumulent des droits de poste en poste."),
(2,"Qu'est-ce que l'IGA ?","La gouvernance et l'administration des identités (demandes, approbations, revues)","Un protocole réseau","Un logiciel de bureautique","Un format de fichier",
 "Elle outille le cycle de vie, les certifications et les contrôles de séparation des tâches."),
(2,"Qu'est-ce que la certification (recertification) d'accès ?","Une revue où les responsables confirment ou retirent les droits de leurs équipes","Un diplôme de sécurité","Un certificat de serveur","Une sauvegarde",
 "Elle apporte la preuve que les droits sont justifiés."),
(2,"Qu'est-ce qu'un PAM ?","La gestion des accès à privilèges","Un protocole d'accès mobile","Un panneau d'accès manuel","Un plan d'audit mensuel",
 "Privileged Access Management : contrôle, enregistrement et limitation des comptes à privilèges."),
(2,"Quelle fonction d'un coffre-fort de mots de passe PAM réduit le risque de partage de comptes ?","L'injection de l'identifiant sans le montrer à l'administrateur","Le fond d'écran","La suppression du compte","Le tri des journaux",
 "L'administrateur utilise le compte sans connaître son secret."),
(2,"Qu'est-ce que l'enregistrement de session privilégiée ?","La capture des actions d'un administrateur pour audit","La sauvegarde du disque","Une copie des fichiers","L'impression des journaux",
 "Il permet de rejouer ce qui a été fait lors d'une intervention."),
(2,"Qu'est-ce que l'accès « juste-à-temps » (JIT) ?","Un privilège accordé pour une durée limitée à la demande","Un privilège permanent","Un accès sans identité","Un accès à toute heure",
 "Il réduit la fenêtre pendant laquelle un compte élevé peut être abusé."),
(2,"Qu'est-ce qu'un privilège permanent (« standing privilege ») ?","Un droit élevé toujours actif, même sans besoin immédiat","Un droit expiré","Un droit en lecture","Un droit supprimé",
 "Il augmente le risque : on préfère l'élévation temporaire."),
(2,"Quelle population doit être traitée en priorité par une démarche PAM ?","Les administrateurs et les comptes de service","Les visiteurs","Les clients","Les fournisseurs de café",
 "Ce sont les comptes dont la compromission a le plus d'impact."),
(2,"Quelle faute évite un compte nominatif d'administration distinct du compte de messagerie ?","Une compromission par un courriel piégé qui donne directement les droits d'administrateur","La perte de mot de passe","L'oubli d'une sauvegarde","Un changement de poste",
 "On isole l'usage à risque (courrier, navigation) des droits élevés."),
(1,"Qu'est-ce qu'un compte nominatif ?","Un compte attribué à une seule personne identifiée","Un compte partagé","Un compte invité","Un compte anonyme",
 "Il garantit l'imputabilité."),
(2,"Quel est l'effet d'un compte générique « admin » partagé ?","On ne sait pas qui a réalisé une action","Les actions sont tracées par personne","Les droits sont réduits","Le MFA est obligatoire",
 "L'imputabilité est perdue."),
(2,"Que faire des comptes génériques inévitables (par exemple appareils) ?","Les inventorier, en nommer un responsable et en gérer le secret dans un coffre","Les ignorer","Les partager par courriel","Les laisser sans mot de passe",
 "On compense l'absence d'identité individuelle par la responsabilité et la traçabilité."),
(2,"Quelle règle s'applique à la rotation d'un mot de passe d'administrateur après usage d'urgence ?","Le changer immédiatement après l'usage","Ne jamais le changer","Le publier","Le laisser dans un courriel",
 "Un secret ayant été vu ou utilisé en urgence doit être renouvelé."),
(3,"Que recommande le NIST SP 800-63B sur les changements périodiques de mot de passe ?","Ne pas les imposer sans signe de compromission","Les imposer tous les 30 jours","Les imposer chaque jour","Les interdire",
 "Les changements forcés encouragent des variantes prévisibles."),
(3,"Que recommande le NIST SP 800-63B pour la longueur et la composition ?","Privilégier la longueur et vérifier contre les mots de passe compromis plutôt qu'imposer des règles de composition","Imposer des caractères spéciaux et pas de longueur","Interdire les phrases","Imposer huit caractères exactement",
 "Les règles de composition rigides produisent des mots de passe prévisibles."),
(2,"Qu'est-ce que le credential stuffing ?","Tester sur un service des identifiants volés ailleurs","Chiffrer des identifiants","Supprimer des comptes","Dupliquer un annuaire",
 "La réutilisation de mots de passe rend ces attaques efficaces ; le MFA les neutralise en grande partie."),
(2,"Que fait un verrouillage temporaire après plusieurs échecs de connexion ?","Ralentit les attaques par force brute","Supprime le compte","Change le mot de passe","Chiffre le disque",
 "Il doit être calibré pour ne pas permettre le blocage volontaire d'un compte légitime."),
(2,"Comment appelle-t-on une attaque qui teste peu de mots de passe courants sur beaucoup de comptes ?","Le password spraying","L'injection SQL","Le déni de service","L'écoute passive",
 "Elle évite le verrouillage par compte."),
(2,"Quel contrôle détecte le password spraying ?","L'analyse des échecs répartis sur de nombreux comptes depuis peu de sources","Le nombre de fichiers","La taille de l'écran","Le niveau de batterie",
 "La corrélation de journaux révèle le motif."),
(2,"Quel est le principal avantage d'une biométrie comme facteur ?","Elle est liée à la personne et pratique","Elle est secrète","Elle est révocable à volonté","Elle ne se trompe jamais",
 "Mais on ne peut pas la changer en cas de fuite : elle sert plutôt à déverrouiller un secret local."),
(3,"Pourquoi une biométrie est-elle mieux utilisée en local qu'envoyée à un serveur ?","Un gabarit biométrique compromis ne peut pas être changé","Elle est trop longue","Elle est trop lente","Elle est chiffrée",
 "Dans FIDO2, la biométrie déverrouille la clé privée sur l'appareil sans quitter celui-ci."),
(2,"Quelle donnée un fournisseur d'identité ne doit-il jamais transmettre à une application ?","Le mot de passe de l'utilisateur","Son identifiant","Son adresse de courriel","Son service",
 "L'application reçoit une assertion ou un jeton, jamais le mot de passe."),
(2,"Que doit contrôler un fournisseur de service en recevant une assertion SAML ?","La signature, l'émetteur, la validité temporelle et le destinataire","Le fond d'écran","La couleur","La taille du fichier",
 "Sans ces contrôles, une assertion falsifiée ou rejouée serait acceptée."),
(3,"Quel risque accompagne un jeton d'accès volé ?","Il permet d'utiliser l'API tant qu'il est valide, même sans mot de passe","Il supprime le compte","Il change le mot de passe","Il est inutilisable",
 "D'où la courte durée de vie et la possibilité de révocation."),
(2,"Que signifie le principe de « portée minimale » (scope) pour un jeton ?","Limiter ce que le jeton autorise aux actions nécessaires","Limiter sa taille","Limiter le nombre d'utilisateurs","Limiter la couleur",
 "C'est le moindre privilège appliqué aux API."),
(3,"Pourquoi faut-il valider la redirection autorisée dans OAuth ?","Pour empêcher qu'un attaquant reçoive le code ou le jeton à sa place","Pour accélérer la connexion","Pour réduire la taille","Pour supprimer les jetons",
 "Une URI de redirection mal contrôlée permet de détourner l'autorisation."),
(2,"Quelle donnée appartient à l'« identité numérique » d'un salarié ?","Ses attributs (nom, service, fonction) et ses comptes","Son numéro de chaussures","Sa couleur préférée","La météo",
 "Ces attributs alimentent les rôles et les règles d'accès."),
(2,"Quelle source est la plus fiable pour l'attribut « service » ?","Le système RH, source autoritative","L'utilisateur lui-même","Un tableur partagé","Un courriel",
 "Une source RH évite que l'attribut soit modifié par celui qui en bénéficie."),
(3,"Quel risque pose un annuaire qui n'est pas synchronisé avec les départs RH ?","Des comptes d'anciens salariés restent actifs","Le serveur est plus rapide","Les journaux sont plus petits","Les groupes disparaissent",
 "Les comptes orphelins sont une porte d'entrée classique."),
(2,"Quel contrôle détecte les comptes inactifs ?","Un rapport des dernières connexions avec désactivation après un délai","Un fond d'écran","Un nouveau mot de passe","Une sauvegarde",
 "Les comptes non utilisés sont désactivés puis supprimés selon la politique."),
(2,"Quelle donnée un bon processus de départ doit-il traiter en plus du compte principal ?","Les accès externes, clés, badges et jetons","Le fond d'écran","Les photos de vacances","Le nom du bureau",
 "Le retrait doit couvrir tous les moyens d'accès."),
]
